from six import string_types
import logging
import re


def remove_escape_sequences(input_str):
    if not input_str:
        return input_str

    compiled_pattern = re.compile(r'''
    (?: # either 7-bit C1, two bytes, ESC Fe (omitting CSI)
        \x1B
        [@-Z\\-_]
    |   # or a single 8-bit byte Fe (omitting CSI)
        [\x08\x80-\x9A\x9C-\x9F]
    |   # or CSI + control codes
        (?: # 7-bit CSI, ESC [
            \x1B\[
        |   # 8-bit CSI, 9B
            \x9B
        )
        [0-?]*  # Parameter bytes
        [ -/]*  # Intermediate bytes
        [@-~]   # Final byte
    )''', re.VERBOSE)

    output_str = compiled_pattern.sub('', input_str)
    return output_str.strip()


class Command:
    def __init__(self, connection):
        self._connection = connection

    def execute(self, **kwargs):

        for key, value in kwargs.items():
            if isinstance(value, string_types) and (-1 != value.find(' ')):
                kwargs[key] = f'"{value}"'

        timeout = kwargs.get('timeout', 10)
        command = self._generate(**kwargs)

        output = self._connection.execute(command=command, timeout=timeout)
        output = remove_escape_sequences(output)
        logging.debug(f"output is: {output}")
        return self._parse_output(output)

    def _generate(self, **kwargs):
        raise NotImplementedError()

    def _parse_output(self, content):
        return content

    def _split_lines(self, content):
        return [line.strip() for line in content.split('\n')]

    def _split_columns(self, line):
        return [column.strip() for column in line.split('   ') if column.strip()]

    def __call__(self, **kwargs):
        return self.execute(**kwargs)
